import collections
def closures(evs, lo, hi, delta=800):
    adj=collections.defaultdict(list)
    for u,v,t in evs:
        adj[u].append((t,v)); adj[v].append((t,u))
    res=[]
    for u,v,t in evs:
        if not (lo<=t<=hi): continue
        na=collections.defaultdict(list); nb=collections.defaultdict(list)
        for tt,c in adj[u]:
            if tt<t: na[c].append(tt)
        for tt,c in adj[v]:
            if tt<t: nb[c].append(tt)
        for c in set(na)&set(nb):
            if c==u or c==v: continue
            supp=max(max(na[c]),max(nb[c]))
            if t-supp<=delta:
                res.append((u,v,t,c,supp))
    return res
r=closures(events,33039,45039)
cnt=collections.defaultdict(int)
for u,v,t,c,s in r: cnt[u]+=1;cnt[v]+=1;cnt[c]+=1
top=sorted(cnt.items(), key=lambda x:-x[1])[:25]
print("n closures", len(r))
print([ (int(a),int(b)) for a,b in top])
print([(int(u),int(v),int(t),int(c),int(s)) for u,v,t,c,s in r[:12]])

import collections
def count_cl(evs, lo, hi, delta=800):
    adj=collections.defaultdict(list)
    for u,v,t in evs:
        adj[u].append((t,v)); adj[v].append((t,u))
    n=0; m=0
    for u,v,t in evs:
        if not (lo<=t<=hi): continue
        m+=1
        na={}; nb={}
        for tt,c in adj[u]:
            if tt<t and (c not in na or tt>na[c]): na[c]=tt
        for tt,c in adj[v]:
            if tt<t and (c not in nb or tt>nb[c]): nb[c]=tt
        for c in set(na)&set(nb):
            if c==u or c==v: continue
            if t-max(na[c],nb[c])<=delta: n+=1
    return n,m
